using System;using System.IO;using UnityEditor;using UnityEngine;using SkyIsland;
public static class NatureSampleReview {
 static readonly string[] names={"CommonTree_1","Rock_Medium_1","Grass_Common_Short","Flower_3_Group"};
 public static void Assign(SkyIslandPrototype p){const string cutoutPath="Assets/SkyIsland/Materials/NatureCutout.mat";var cutout=AssetDatabase.LoadAssetAtPath<Material>(cutoutPath);if(!cutout){cutout=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(cutout,cutoutPath);}cutout.SetFloat("_Mode",1);cutout.SetFloat("_Cutoff",.4f);cutout.EnableKeyword("_ALPHATEST_ON");cutout.renderQueue=2450;EditorUtility.SetDirty(cutout);p.NatureFoliageMaterial=cutout;p.NatureSamples=new GameObject[names.Length];for(int i=0;i<names.Length;i++){string path="Assets/ExternalLibrary/stylized-nature-standard/FBX (Unity)/"+names[i]+".fbx";var importer=AssetImporter.GetAtPath(path) as ModelImporter;if(importer==null)throw new Exception("Missing nature asset "+path);importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.materialLocation=ModelImporterMaterialLocation.InPrefab;importer.SaveAndReimport();p.NatureSamples[i]=AssetDatabase.LoadAssetAtPath<GameObject>(path);}}
 public static void BuildReviewedWeb(){CapturePreview();PrototypeBuild.BuildWeb();}
 public static void CapturePreview(){PrototypeBuild.Prepare();PanelReview.Validate();NatureResourceReview.Validate();Validate();var prototype=UnityEngine.Object.FindObjectOfType<SkyIslandPrototype>();prototype.SendMessage("Awake");HarborReview.Scene(prototype);int instances=0;foreach(var t in UnityEngine.Object.FindObjectsOfType<Transform>())if(t.name.StartsWith("Nature sample ")){instances++;foreach(var c in t.GetComponentsInChildren<Collider>())if(c.enabled&&!c.isTrigger)throw new Exception("Resource collider must be trigger-only");}if(instances!=NatureRules.Target)throw new Exception("Fresh scene expected fifty resources, actual "+instances);File.WriteAllText("../evidence/assets/nature-scene-inspection.txt","PASS 50 instantiated renewable samples; enabled colliders are trigger-only; editor-assembled scene, not browser interaction; UTC "+DateTime.UtcNow.ToString("o"));var camera=Camera.main;if(!camera)throw new Exception("Missing game camera");var target=new RenderTexture(1280,720,24);camera.targetTexture=target;camera.Render();RenderTexture.active=target;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes("../evidence/assets/nature-preview.png",image.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(target);UnityEngine.Object.DestroyImmediate(image);Debug.Log("SKY_NATURE_PREVIEW_CAPTURED");}
 public static void Validate(){int vertices=0;var foliage=AssetDatabase.LoadAssetAtPath<Material>("Assets/SkyIsland/Materials/NatureCutout.mat");if(!foliage||!foliage.IsKeywordEnabled("_ALPHATEST_ON"))throw new Exception("Cutout shader variant missing from referenced assets");foreach(var name in names){string path="Assets/ExternalLibrary/stylized-nature-standard/FBX (Unity)/"+name+".fbx";var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!model)throw new Exception("Missing sample "+name);var renderers=model.GetComponentsInChildren<Renderer>();if(renderers.Length==0)throw new Exception("No renderer "+name);foreach(var mesh in model.GetComponentsInChildren<MeshFilter>())vertices+=mesh.sharedMesh.vertexCount;foreach(var r in renderers)foreach(var m in r.sharedMaterials)if(!m||!m.shader||!m.mainTexture)throw new Exception("Missing material/texture "+name);}Directory.CreateDirectory("../evidence/assets");File.WriteAllText("../evidence/assets/nature-scene-tests.txt","PASS four selected FBX models with renderers/materials/textures; vertices "+vertices+"; Unity "+Application.unityVersion+"; UTC "+DateTime.UtcNow.ToString("o")+"\nImport/reference validation only; visual and mobile performance review pending.");Debug.Log("SKY_NATURE_TESTS_PASS 4");}
}
